mapper.select:
select a.REGIST_SEQNO from (
    SELECT
    @rownum:=@rownum+1 `rownum`,
    REGIST_SEQNO,
    IF
    (
    (
    @VAL_DATE = A.VAL_DATE
    AND @ASSET_CODE = A.ASSET_CODE
    ),
    @rank := @rank + 1,
    @rank := 1
    ) AS myrank,
    @VAL_DATE := A.VAL_DATE,
    @ASSET_CODE := A.ASSET_CODE
    FROM
    ( SELECT * FROM CHB_AST_VAL_SUB_HIS ORDER BY VAL_DATE,ASSET_CODE, ifnull( UPDATE_TIME, CREATE_TIME ) DESC ) A,
    (
    SELECT
    @rownum := 0,
    @VAL_DATE := NULL,
    @ASSET_CODE := NULL,
    @rank := 0
    ) B
   where

    ASSET_CODE = #{item.assetCode}
    and VAL_DATE = #{item.valDate}

)a
where 1 = 1 limit 1
